"When does school start?":"متى تبدأ المدرسة؟",
"Verbs: present tense":"الأفعال: الزمن الحاضر",
"I speak a little Norwegian.":"أتكلّم قليلًا من النرويجية.",
"We live in Norway.":"نسكن في النرويج.",
"Modal verbs":"الأفعال المساعدة",
"I can speak a little Norwegian.":"أستطيع أن أتكلّم قليلًا من النرويجية.",
"We are going to travel to Tromsø.":"سنسافر إلى ترومسو.",
"I like to read.":"أحب القراءة.",
"Nouns: en, ei, et":"الأسماء: en وei وet",
"I have a cat. The cat is called Pus.":"عندي قط. القط اسمه بوس.",
"We live in a house. The house is yellow.":"نسكن في بيت. البيت أصفر.",
"Object pronouns":"ضمائر المفعول به",
