"Dad, what are we going to do this weekend?":"أبي، ماذا سنفعل في عطلة نهاية الأسبوع؟",
"I think we are going to have a picnic.":"أظن أننا سنذهب في نزهة.",
"Yes! Can we go to the lake?":"نعم! هل يمكننا الذهاب إلى البحيرة؟",
"Good idea. But first let us check the weather.":"فكرة جيدة. لكن أولًا لنتحقق من الطقس.",
"It is going to be sunny and warm on Saturday.":"سيكون الجو مشمسًا ودافئًا يوم السبت.",
"Perfect! I am going to make sandwiches.":"رائع! سأعدّ السندويشات.",
"Can I invite my friend Humphrey too?":"هل يمكنني أن أدعو صديقي همفري أيضًا؟",
"Of course. The more, the merrier!":"بالتأكيد. كلما زاد العدد كان ذلك أجمل!",
