"Lost in the City":"ضائع في المدينة",
"Excuse me, could you help me? I think I am lost.":"عذرًا، هل يمكنك مساعدتي؟ أعتقد أنني ضعت.",
"Of course. Where do you want to go?":"بالطبع. إلى أين تريد الذهاب؟",
"I am looking for the city library.":"أنا أبحث عن مكتبة المدينة.",
"Go straight on and turn left at the traffic lights.":"اذهب مستقيمًا ثم انعطف يسارًا عند إشارات المرور.",
"Then walk past the bus stop. The library is opposite the bank.":"ثم امشِ بعد موقف الحافلات. المكتبة مقابل البنك.",
"Is it far from here?":"هل هي بعيدة من هنا؟",
"No, it only takes about ten minutes on foot.":"لا، لا يستغرق الأمر سوى حوالي عشر دقائق سيرًا على الأقدام.",
"Great. And is there a café near the library?":"رائع. وهل يوجد مقهى بالقرب من المكتبة؟",
"Later, Ruslan took the wrong bus.":"لاحقًا، استقل روسلان الحافلة الخاطئة.",
"This bus does not go there. Get off at the next stop and cross the road.":"هذه الحافلة لا تذهب إلى هناك. انزل عند المحطة التالية واعبر الطريق.",
"Finally! The library is on the corner, just like you said.":"أخيرًا! المكتبة على الزاوية، تمامًا كما قلت.",
