"on the corner":"عند الزاوية",
"Grammar in real life":"القواعد في الحياة الواقعية",
"What is coding?":"ما هي البرمجة؟",
"The school has a robot called Robo. He only follows exact commands, and the children learn that a program is commands in the right order.":"في المدرسة روبوت اسمه روبو. ينفّذ الأوامر الدقيقة فقط، ويتعلّم الأطفال أن البرنامج أوامر بالترتيب الصحيح.",
"Look, Nora! The school has got a robot.":"انظري يا نورا! صار في المدرسة روبوت.",
"Hi, robot! What is your name?":"مرحبًا يا روبوت! ما اسمك؟",
"Hi! My name is Robo. I do what you tell me.":"مرحبًا! اسمي روبو. أفعل ما تقولونه لي.",
"Robo only understands commands. We call that programming.":"روبو يفهم الأوامر فقط. وهذا ما نسمّيه البرمجة.",
"What is a command?":"ما هو الأمر؟",
"A command is a short instruction, for example “walk” or “turn”.":"الأمر تعليمة قصيرة، مثل «امشِ» أو «استدِر».",
"Robo, take two steps forward!":"روبو، تقدّم خطوتين إلى الأمام!",
"Walking. One, two. Done!":"أمشي. واحد، اثنان. انتهيت!",
"Robo, make me a pizza!":"روبو، اصنع لي بيتزا!",
"Error! I do not know the command “pizza”.":"خطأ! لا أعرف الأمر «بيتزا».",
"A program is many commands in the right order.":"البرنامج أوامر كثيرة بالترتيب الصحيح.",
"So we have to think step by step!":"إذن علينا أن نفكّر خطوة بخطوة!",
"I want to learn to code!":"أريد أن أتعلّم البرمجة!",
"And I want to learn to make pizza.":"وأنا أريد أن أتعلّم صنع البيتزا.",
"a robot":"روبوت",
