"right, correct":"صحيح",
"step by step":"خطوة بخطوة",
"The sandwich algorithm":"خوارزمية الشطيرة",
"Leo teaches Robo the robot to make a sandwich. Robo does everything literally, so Leo learns that an algorithm must be exact and in the right order.":"يعلّم ليو الروبوت روبو صنع شطيرة. ينفّذ روبو كل شيء حرفيًا، فيتعلّم ليو أن الخوارزمية يجب أن تكون دقيقة وبالترتيب الصحيح.",
"Dad, I am going to teach Robo to make a sandwich.":"بابا، سأعلّم روبو صنع شطيرة.",
"Then you need an algorithm.":"إذن تحتاج إلى خوارزمية.",
"What is an algorithm?":"ما هي الخوارزمية؟",
"An algorithm is like a recipe: step by step, in the right order.":"الخوارزمية مثل الوصفة: خطوة بخطوة وبالترتيب الصحيح.",
"Step one: Take the bread. Step two: Put on butter.":"الخطوة الأولى: خذ الخبز. الخطوة الثانية: ضع الزبدة.",
"Butter on … the table? Done!":"الزبدة على… الطاولة؟ تمّ!",
"Ha ha! You have to say exactly what Robo should do.":"ها ها! عليك أن تقول بدقة ما يجب أن يفعله روبو.",
"New step two: Put butter on the slice of bread!":"الخطوة الثانية الجديدة: ضع الزبدة على شريحة الخبز!",
"Step three: Put on cheese. Step four: Give the sandwich to Leo.":"الخطوة الثالثة: ضع الجبن. الخطوة الرابعة: أعطِ الشطيرة لليو.",
"Done! Here you are.":"تمّ! تفضّل.",
"Mmm! The algorithm works!":"ممم! الخوارزمية تعمل!",
"And remember: the order is important. First butter, then cheese.":"وتذكّر: الترتيب مهم. أولًا الزبدة ثم الجبن.",
"an algorithm":"خوارزمية",
"a slice of bread, a sandwich":"شريحة خبز، شطيرة",
"a cheese":"جبن",
"to put on":"يضع فوق",
"done, carried out":"تمّ، نُفّذ",
"then":"ثم",
"Repeat! Robo dances":"كرّر! روبو يرقص",
"Nora wants Robo to dance, but there are too many commands. The teacher shows a loop: “repeat 4 times” — and the program becomes short.":"تريد نورا أن يرقص روبو، لكن الأوامر كثيرة جدًا. تُريها المعلّمة حلقة: «كرّر 4 مرات» — فيصبح البرنامج قصيرًا.",
"Robo, jump! Clap! Jump! Clap! Jump! Clap!":"روبو، اقفز! صفّق! اقفز! صفّق! اقفز! صفّق!",
"Jump. Clap. Jump. Clap …":"قفزة. تصفيق. قفزة. تصفيق…",
"Phew, that is a lot to write.":"أوف، هذا كثير للكتابة.",
"Use a loop! A loop repeats commands.":"استخدمي حلقة! الحلقة تكرّر الأوامر.",
"Write: repeat four times: jump and clap.":"اكتبي: كرّر أربع مرات: اقفز وصفّق.",
"So short!":"قصير جدًا!",
"Jump, clap! Jump, clap! Jump, clap! Jump, clap!":"قفزة، تصفيق! قفزة، تصفيق! قفزة، تصفيق! قفزة، تصفيق!",
"Robo is dancing!":"روبو يرقص!",
"Can we repeat it a hundred times?":"هل يمكن أن نكرّرها مئة مرة؟",
"Yes. Computers never get tired.":"نعم. الحواسيب لا تتعب أبدًا.",
"But Robo is getting dizzy …":"لكن روبو بدأ يشعر بالدوار…",
"Ha ha! We are stopping the loop now.":"ها ها! سنوقف الحلقة الآن.",
"a loop":"حلقة",
"to jump":"يقفز",
"to clap":"يصفّق",
"a lot":"كثير",
"to use":"يستخدم",
"four times":"أربع مرات",
"a hundred":"مئة",
"to stop":"يوقف",
"If it rains …":"إذا أمطرت…",
"Robo does not know when to take an umbrella. Leo and Mum write him a rule: if it rains — an umbrella, otherwise — sunglasses.":"لا يعرف روبو متى يأخذ المظلة. يكتب له ليو وأمه قاعدة: إذا أمطرت فالمظلة، وإلا فالنظارات الشمسية.",
"Robo, we are going out. Bring an umbrella.":"روبو، سنخرج. خذ معك مظلة.",
"Why? The sun is shining.":"لماذا؟ الشمس مشرقة.",
"You are right, Robo. We need a rule.":"أنت محقّ يا روبو. نحتاج إلى قاعدة.",
"If it rains, we take an umbrella.":"إذا أمطرت نأخذ المظلة.",
"If it rains, then we take an umbrella. Otherwise we take sunglasses.":"إذا أمطرت فإننا نأخذ المظلة. وإلا نأخذ النظارات الشمسية.",
"If … then … otherwise. Understood!":"إذا… فإن… وإلا. فهمت!",
"It is raining. I am taking the umbrella.":"إنها تمطر. سآخذ المظلة.",
"Good, Robo!":"أحسنت يا روبو!",
"Now the sun is shining. I am taking sunglasses.":"الآن الشمس مشرقة. سآخذ النظارات الشمسية.",
"Robo thinks like a computer.":"روبو يفكّر مثل الحاسوب.",
"If I tidy my room, then I get ice cream?":"إذا رتّبت غرفتي، هل أحصل على مثلّجات؟",
"Yes! That is a good rule.":"نعم! هذه قاعدة جيدة.",
"otherwise, else":"وإلا",
"an umbrella":"مظلة",
"sunglasses":"نظارات شمسية",
"the sun is shining":"الشمس مشرقة",
"to go out":"يخرج",
"to bring":"يأخذ معه",
"to be right":"يكون محقًا",
"understood":"مفهوم",
"to think":"يفكّر",
"Points in the box":"النقاط في الصندوق",
"Nora and Leo make a game: a cat catches fish and gets points. The teacher explains a variable — a box with a name where the computer keeps a number.":"تصنع نورا وليو لعبة: قطة تصطاد السمك وتحصل على نقاط. تشرح المعلّمة المتغيّر — صندوق له اسم يحفظ فيه الحاسوب رقمًا.",
"We are making a game! Every time the cat catches a fish, we get a point.":"نصنع لعبة! كلما اصطادت القطة سمكة نحصل على نقطة.",
"But where will the computer remember the points?":"لكن أين سيتذكّر الحاسوب النقاط؟",
"In a variable. A variable is like a box with a name.":"في متغيّر. المتغيّر مثل صندوق له اسم.",
"The box is called “points”. Right now there is zero in the box.":"اسم الصندوق «النقاط». الآن يوجد فيه صفر.",
"The cat catches a fish!":"القطة تصطاد سمكة!",
"Then we write: points equals points plus one.":"إذن نكتب: النقاط تساوي النقاط زائد واحد.",
"Points is one. Points is two. Points is three!":"النقاط واحد. النقاط اثنان. النقاط ثلاثة!",
"The value in the box changes!":"القيمة في الصندوق تتغيّر!",
"Can we have more boxes?":"هل يمكن أن يكون لدينا صناديق أكثر؟",
"Yes. Name, lives and speed … A game has many variables.":"نعم. الاسم والأرواح والسرعة… في اللعبة متغيّرات كثيرة.",
"We have ten points! We won!":"لدينا عشر نقاط! فزنا!",
"The variable “joy” is now a hundred.":"المتغيّر «الفرح» صار الآن مئة.",
