"to keep, to take care of":"يحفظ، يعتني بـ",
"Find the bug!":"اعثر على الخطأ!",
"Robo has to reach the star but walks into a wall. The children read the program line by line, find the bug and fix it.":"على روبو أن يصل إلى النجمة لكنه يصطدم بالجدار. يقرأ الأطفال البرنامج سطرًا سطرًا، فيجدون الخطأ ويصلحونه.",
"Robo has to walk to the star. I have written the program.":"على روبو أن يمشي إلى النجمة. لقد كتبت البرنامج.",
"I am starting the program now.":"سأشغّل البرنامج الآن.",
"Ouch! I walked straight into the wall.":"آخ! مشيت مباشرة نحو الجدار.",
"Oops! The program has a bug.":"أوه! في البرنامج خطأ.",
"We call an error in a program a bug.":"نسمّي الخطأ في البرنامج «علّة» (bug).",
"Finding and fixing the error is called debugging.":"إيجاد الخطأ وإصلاحه يسمّى تصحيح الأخطاء.",
"We read the program line by line: forward, forward, right …":"نقرأ البرنامج سطرًا سطرًا: إلى الأمام، إلى الأمام، يمين…",
"There! It should say left, not right.":"هنا! يجب أن يكون يسار، لا يمين.",
"Now I will fix the bug and try again.":"سأصلح الخطأ الآن وأحاول مرة أخرى.",
"I am at the star! The program works.":"وصلت إلى النجمة! البرنامج يعمل.",
"All programmers make mistakes. The important thing is to try again.":"كل المبرمجين يخطئون. المهم أن نحاول مرة أخرى.",
"Mistakes are part of learning!":"الأخطاء جزء من التعلّم!",
