"debugging":"تصحيح الأخطاء",
"to fix, to correct":"يصلح",
"right":"يمين",
"to try again":"يحاول مرة أخرى",
"learning":"التعلّم",
"a part of":"جزء من",
"Which language?":"أي لغة؟",
"Leo asks Robo which language he speaks. The teacher explains programming languages: Scratch, Python, JavaScript, HTML and CSS, Swift, Kotlin and C#.":"يسأل ليو روبو بأي لغة يتكلّم. تشرح المعلّمة لغات البرمجة: Scratch وPython وJavaScript وHTML وCSS وSwift وKotlin وC#.",
"Robo, which language do you speak? Norwegian?":"روبو، بأي لغة تتكلّم؟ بالنرويجية؟",
"I understand programming languages. There are many!":"أفهم لغات البرمجة. وهي كثيرة!",
"Children often start with Scratch. There we move colourful blocks.":"يبدأ الأطفال غالبًا بـScratch. وفيه نحرّك كتلًا ملوّنة.",
"It looks like Lego!":"يشبه الليغو!",
"Python is easy to read. It is used for games, data and artificial intelligence.":"بايثون سهلة القراءة. تُستخدم للألعاب والبيانات والذكاء الاصطناعي.",
"Artificial intelligence? Like Robo?":"ذكاء اصطناعي؟ مثل روبو؟",
"HTML builds web pages, and CSS makes them pretty. JavaScript makes them move.":"HTML يبني صفحات الويب، وCSS يجمّلها، وJavaScript يجعلها تتحرّك.",
"So the school website is made with them?":"إذن موقع المدرسة مصنوع بها؟",
"We make iPhone apps with Swift, and Android apps with Kotlin.":"نصنع تطبيقات آيفون بلغة Swift، وتطبيقات أندرويد بلغة Kotlin.",
"And games?":"والألعاب؟",
"Many games are made with C#.":"كثير من الألعاب تُصنع بلغة C#.",
"Which language should I learn first?":"أي لغة يجب أن أتعلّمها أولًا؟",
"Start with Scratch or Python. The most important thing is to think logically.":"ابدأ بـScratch أو Python. الأهم أن تفكّر بشكل منطقي.",
"a programming language":"لغة برمجة",
"to exist":"يوجد",
"colourful":"ملوّن",
"a block":"كتلة",
"simple, easy":"بسيط، سهل",
"artificial intelligence":"الذكاء الاصطناعي",
"data":"بيانات",
"a web page, a website":"صفحة ويب، موقع",
"logically":"بشكل منطقي",
"the most important thing":"الأهم",
"A model of the school":"نموذج للمدرسة",
"The class makes a model of the schoolyard. The children learn that a model is a simple copy, that things in a program have properties, and that you draw the plan before the code.":"يصنع الصف نموذجًا لساحة المدرسة. يتعلّم الأطفال أن النموذج نسخة بسيطة، وأن للأشياء في البرنامج خصائص، وأننا نرسم الخطة قبل الشيفرة.",
"Today we are making a model of the schoolyard.":"اليوم نصنع نموذجًا لساحة المدرسة.",
"What is a model?":"ما هو النموذج؟",
"A model is a simple copy of something real. A map is a model too.":"النموذج نسخة بسيطة من شيء حقيقي. والخريطة أيضًا نموذج.",
"Like the map in a game!":"مثل الخريطة في لعبة!",
"We only draw the important things: the school, the gate and the football pitch.":"نرسم المهم فقط: المدرسة والبوابة وملعب كرة القدم.",
"We do not need to draw every single leaf.":"لا نحتاج إلى رسم كل ورقة شجر.",
"In a program we describe things with properties. A ball has a colour, a size and a speed.":"في البرنامج نصف الأشياء بخصائصها. للكرة لون وحجم وسرعة.",
"So the ball is white and fast!":"إذن الكرة بيضاء وسريعة!",
