"A website for Pus: HTML basics":"موقع لبوس: أساسيات HTML",
"Nora and Leo make a website about Pus the cat. Robo explains HTML: tags in angle brackets, a heading <h1>, a paragraph <p>, an image <img> and a link <a>.":"تصنع نورا وليو موقعًا عن القط بوس. يشرح روبو HTML: الوسوم بين قوسين زاويين، والعنوان <h1>، والفقرة <p>، والصورة <img>، والرابط <a>.",
"I want to make a website about our cat, Pus!":"أريد أن أصنع موقعًا عن قطّنا بوس!",
"Then we need HTML.":"إذن نحتاج إلى HTML.",
"HTML builds web pages. It is made of tags.":"HTML يبني صفحات الويب. ويتكوّن من وسوم.",
"What is a tag?":"ما هو الوسم؟",
"A tag is a short word in angle brackets, for example p.":"الوسم كلمة قصيرة بين قوسين زاويين، مثل p.",
"Most tags have a start and an end. The end tag has a slash.":"لمعظم الوسوم بداية ونهاية. ووسم النهاية فيه شرطة مائلة.",
"Like a sandwich!":"مثل الشطيرة!",
"I write h1 and “Pus”. It becomes a big heading!":"أكتب h1 و«بوس». فيصير عنوانًا كبيرًا!",
"Yes. h1 means heading number one.":"نعم. h1 تعني العنوان رقم واحد.",
"With p we make a paragraph, and with img we show a picture.":"بـp نصنع فقرة، وبـimg نعرض صورة.",
"Look, a picture of Pus!":"انظر، صورة لبوس!",
"Finally a link. The a tag takes us to another page.":"وأخيرًا رابط. الوسم a يأخذنا إلى صفحة أخرى.",
"The website is ready! Next time we will make it pretty with CSS.":"الموقع جاهز! في المرة القادمة سنجمّله بـCSS.",
